/** Instructional content for the Voice program. This file is the single source: the staff pages, the student unit pages and the database seed
 *  (supabase/migrations/..._dp_voice_curriculum_seed.sql, generated by scripts/generate-curriculum-seed.mjs) are all produced from it. */
export type Level = "beginner" | "intermediate" | "advanced";
export const LEVELS: Level[] = ["beginner", "intermediate", "advanced"];
export type TrackKey = "worship_leadership" | "spontaneous_expression" | "prophetic_worship";
export const TRACK_KEYS: TrackKey[] = ["worship_leadership", "spontaneous_expression", "prophetic_worship"];

export interface Difficulty { issue: string; adjust: string }
export interface ExerciseSpec {
  key: string;
  title: string;
  level: Level | "all";
  minutes: number;
  /** Shown to the student when the exercise is assigned: plain, step-by-step practice instructions. */
  student: string;
  /** Staff only: how to demonstrate it. */
  demonstrate: string;
  /** Staff only: what to listen and look for, and how to coach it. */
  coach: string;
  /** Staff only. */
  difficulties: Difficulty[];
  /** Staff only: optional cautions. */
  safety?: string;
  /** Never auto-selected into a draft plan. The instructor may add it only when the student explicitly requested it. */
  onlyOnRequest?: boolean;
}
export interface AssignmentSpec { key: string; title: string; level: Level | "all"; minutes: number; steps: string[] }
export interface LevelSpec { focus: string; goals: string[] }
export interface ProgressIndicator { indicator: string; measure: string }

export interface AreaSpec {
  key: string;
  number: number;
  title: string;
  /** dp_voice_skills.slug this area's exercises are filed under. */
  skillSlug: string;
  /** Optional track (opt-in creative worship areas only). */
  track?: TrackKey;
  /** What this area is, for the student. */
  studentSummary: string;
  /** Staff only. */
  instructorSummary: string;
  assessment: { tasks: string[]; indicators: string[] };
  levels: Record<Level, LevelSpec>;
  /** Staff only: an ordered teaching outline for a lesson on this area. */
  outline: string[];
  exercises: ExerciseSpec[];
  assignments: AssignmentSpec[];
  progress: ProgressIndicator[];
  followUp: { when: string; tasks: string[]; looksLike: string[] };
  /** Staff only: honest limits and when to bring in outside help. */
  instructorCaution?: string;
  /** Words in a student's goals that point to this area. */
  keywords: string[];
  scripture?: { ref: string; use: string }[];
}

export const GENERAL_SAFETY = "Stop and rest if you feel pain, tightness, burning, a catch in the voice, or light-headedness. Sing at a comfortable volume, drink water, and never push through strain. Ongoing hoarseness or discomfort lasting more than two weeks is a reason to see a doctor.";
